using System.Globalization;

namespace SeleneFrontend.Models;

/// <summary>
/// <c>data/science/psr.json</c> (generated by <c>pipeline/build_psr.py</c> from NASA's LOLA map of permanently shadowed
/// regions, Mazarico et al. 2011): distance from each site and each Wueller et al. (2026) candidate to the nearest PSR
/// — where water ice can be trapped — and simplified PSR outlines near the sites. Optional: the app works without it.
/// UI-free (linked into SeleneFrontend.Tests).
/// </summary>
public sealed class PsrScience
{
    public string Product { get; set; } = "";
    public string Citation { get; set; } = "";
    public string Url { get; set; } = "";
    public string Definition { get; set; } = "";
    public double TotalPsrKm2 { get; set; }
    public double OutlineRadiusKm { get; set; }
    public List<PsrSite> Sites { get; set; } = [];
    public List<PsrRegion> Regions { get; set; } = [];

    public PsrSite? SiteFor(string? siteId) => siteId is null ? null : Sites.FirstOrDefault(s => s.SiteId == siteId);
    public PsrRegion? RegionFor(string? siteId) => siteId is null ? null : Regions.FirstOrDefault(r => r.SiteId == siteId);
}

public sealed class PsrSite
{
    public string SiteId { get; set; } = "";
    public string Name { get; set; } = "";
    public double Lat { get; set; }
    public double Lon { get; set; }
    public bool OnPsr { get; set; }
    /// <summary>Straight-line distance to the nearest PSR pixel of any size (km).</summary>
    public double DAnyKm { get; set; }
    /// <summary>To the nearest PSR of at least 1 km² (km).</summary>
    public double D1Km { get; set; }
    /// <summary>To the nearest PSR of at least 10 km² (km).</summary>
    public double D10Km { get; set; }
    public double PsrKm2Within2 { get; set; }
    public double PsrKm2Within5 { get; set; }
    public double PsrKm2Within10 { get; set; }
    public PsrNearest? Nearest1 { get; set; }
    public List<PsrOutline> Outlines { get; set; } = [];
}

public sealed class PsrNearest
{
    public double Lat { get; set; }
    public double Lon { get; set; }
    public double AreaKm2 { get; set; }
}

public sealed class PsrOutline
{
    public double AreaKm2 { get; set; }
    public double DistKm { get; set; }
    /// <summary>[ring][vertex] = [lon, lat] (degrees); ring 0 is the outer boundary.</summary>
    public List<List<double[]>> Rings { get; set; } = [];
}

public sealed class PsrRegion
{
    public string SiteId { get; set; } = "";
    public string SunPeriod { get; set; } = "";
    public string SunDefinition { get; set; } = "";
    public List<PsrCandidate> Candidates { get; set; } = [];

    public PsrCandidate? Site => Candidates.FirstOrDefault(c => c.IsSite);

    /// <summary>
    /// The sun-vs-ice alternative: on the Pareto front, closest to a PSR ≥ 1 km², not the site itself, and still lit at
    /// least <paramref name="minSunPct"/> % of the time (a very dark candidate is no landing option for a solar lander).
    /// </summary>
    public PsrCandidate? IceFirst(double minSunPct = 40) =>
        Candidates.Where(c => c.Pareto && !c.IsSite && c.SunPct >= minSunPct && (Site is null || c.D1Km < Site.D1Km))
                  .OrderBy(c => c.D1Km).FirstOrDefault();
}

public sealed class PsrCandidate
{
    public string CandidateId { get; set; } = "";
    public double Lat { get; set; }
    public double Lon { get; set; }
    public double? SlopeDeg { get; set; }
    /// <summary>Hours with at least half of the Sun's disc visible (%), panels 2 m up, 2026-11 … 2035 (candidates/*.json).</summary>
    public double SunPct { get; set; }
    public double EarthPct { get; set; }
    public double? LongestDarkH { get; set; }
    public double DAnyKm { get; set; }
    public double D1Km { get; set; }
    public double PsrKm2Within5 { get; set; }
    public bool IsSite { get; set; }
    /// <summary>Not beaten by another candidate on both more sun and a closer PSR ≥ 1 km².</summary>
    public bool Pareto { get; set; }
}

/// <summary>Plain-language lines about water ice (SIMPLE mode and the site panel).</summary>
public static class PsrText
{
    private static string Km(double v) => v.ToString("0.0", CultureInfo.InvariantCulture) + " km";

    /// <summary>"The nearest crater floor in permanent shadow, where water ice can be trapped, is 10.5 km away."</summary>
    public static string Sentence(PsrSite s) =>
        s.D1Km < 0.05
            ? "This site is at the edge of a crater floor in permanent shadow, where water ice can be trapped."
            : $"The nearest crater floor in permanent shadow (1 km² or more), where water ice can be trapped, is {Km(s.D1Km)} away.";

    /// <summary>"In this region NR201 is 0.3 km from one, but sunlit 45 % of the time instead of 52 %." (null without a trade-off)</summary>
    public static string? TradeOff(PsrRegion r)
    {
        if (r.Site is not { } site || r.IceFirst() is not { } ice) return null;
        var sun = (double v) => Math.Round(v).ToString("0", CultureInfo.InvariantCulture) + "%";
        return ice.SunPct < site.SunPct
            ? $"In this region, candidate {ice.CandidateId} is {Km(ice.D1Km)} from one, but sunlit {sun(ice.SunPct)} of the time instead of {sun(site.SunPct)}."
            : $"In this region, candidate {ice.CandidateId} is {Km(ice.D1Km)} from one and sunlit {sun(ice.SunPct)} of the time.";
    }
}
